    if (!idea.trim()) return;
    setIsGenerating(true); setError(""); setConcept("");
    const systemPrompt = `You are an expert creative director... (same prompt)`;
    try {
      const result = await callGeminiAPI(`My idea is: ${idea}`, systemPrompt);
      setConcept(result);
    } catch (err) { setError("Oops! The AI needs a quick break. Try again in a moment."); } finally { setIsGenerating(false); }
  };

  return (
    <div className="relative rounded-[3rem] bg-white/5 backdrop-blur-[40px] p-10 md:p-16 border border-white/10 shadow-[0_20px_50px_rgba(0,0,0,0.3)] overflow-hidden">
