          <Sparkles className="w-4 h-4 text-purple-400" /> AI Co-Creator
        </div>
        <h3 className="text-3xl md:text-5xl font-bold tracking-tighter mb-4 text-white">Brainstorm your next viral hit.</h3>
        <p className="text-white/60 text-lg mb-8 font-light">Type a raw product or brand idea below.</p>
        
        <div className="flex flex-col sm:flex-row gap-4 mb-8">
          <input 
            type="text" 
            value={idea}
            onChange={(e) => setIdea(e.target.value)}
            placeholder="e.g., A sleek new coffee brand..." 
            className="flex-1 bg-white/5 border border-white/10 rounded-2xl px-6 py-4 text-white focus:outline-none focus:border-white/30 focus:bg-white/10 transition-all shadow-inner placeholder:text-white/30"
            onKeyDown={(e) => e.key === 'Enter' && handleGenerate()}
          />
          <MagneticButton primary onClick={handleGenerate} className="py-4 px-8" disabled={isGenerating}>
            {isGenerating ? <><Loader2 className="w-5 h-5 animate-spin" /> Thinking...</> : "✨ Generate Concept"}
          </MagneticButton>
        </div>

        <AnimatePresence mode="wait">
          {concept && (
            <motion.div 
              initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }}
              className="p-6 rounded-2xl bg-white/5 border border-white/10 shadow-sm"
            >
              <div className="prose prose-invert prose-sm md:prose-base max-w-none text-white/80">
                {concept.split('\n').map((line, i) => {
                  if (line.includes('The Hook:')) return <p key={i}><strong className="text-purple-400">The Hook:</strong> {line.replace(/.*The Hook:\s*/i, '')}</p>;
                  if (line.includes('The Build-up:')) return <p key={i}><strong className="text-blue-400">The Build-up:</strong> {line.replace(/.*The Build-up:\s*/i, '')}</p>;
                  if (line.includes('The CTA:')) return <p key={i}><strong className="text-pink-400">The CTA:</strong> {line.replace(/.*The CTA:\s*/i, '')}</p>;
                  return line ? <p key={i}>{line}</p> : null;
                })}
              </div>
            </motion.div>
          )}
          {error && <p className="text-red-400 font-medium">{error}</p>}
        </AnimatePresence>
      </div>
    </div>
  );
});

