                {[
                  { year: "Present", title: "Professional Video Editor", desc: "Crafting high-end 4K visual content.", align: "right", icon: <Play className="w-4 h-4 text-black" /> },
                  { year: "2025", title: "Biofloc Fish Farming", desc: "Launched second entrepreneurial venture.", align: "left", icon: <Briefcase className="w-4 h-4 text-black" /> },
                  { year: "2023 - 2025", title: "Granite Laser Engraving", desc: "Scaled a part-time school business to ₹6L revenue.", align: "right", icon: <Award className="w-4 h-4 text-black" /> },
                  { year: "The Beginning", title: "Creative Spark", desc: "Discovered the passion for video editing.", align: "left", icon: <Sparkles className="w-4 h-4 text-black" /> }
                ].map((item, index) => (
                  <motion.div key={index} initial={{ opacity: 0, y: 50 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, margin: "-100px" }} transition={{ duration: 0.6, delay: index * 0.1 }} className={`relative flex flex-col md:flex-row items-start md:items-center justify-between mb-16 last:mb-0 ${item.align === 'right' ? 'md:flex-row-reverse' : ''}`}>
                    <div className="absolute left-[-40px] md:left-1/2 w-10 h-10 rounded-full bg-white border-2 border-white flex items-center justify-center -translate-x-1/2 z-10 shadow-[0_0_20px_rgba(255,255,255,0.4)]">{item.icon}</div>
                    <div className={`w-full md:w-[45%] ${item.align === 'right' ? 'md:pl-12 text-left' : 'md:pr-12 md:text-right'} pl-6 md:pl-0`}>
                      <span className="text-white/60 font-mono text-sm tracking-widest font-semibold">{item.year}</span>
                      <h4 className="text-2xl font-bold text-white mt-2 mb-3">{item.title}</h4>
                      <p className="text-white/60 leading-relaxed font-light">{item.desc}</p>
                    </div>
                    <div className="hidden md:block w-[45%]" />
                  </motion.div>
                ))}
              </div>
            </div>
          </section>

          {/* Portfolio Section */}
          <section id="portfolio" className="py-32 px-6 md:px-12 max-w-7xl mx-auto bg-transparent">
            <SectionHeading subtitle="Selected Works">Visual Portfolio.</SectionHeading>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              {[
                { id: 1, title: "Cinematic Reel 01", category: "Motion Design • 4K", videoUrl: "https://www.w3schools.com/html/mov_bbb.mp4" },
                { id: 2, title: "Cinematic Reel 02", category: "VFX • 4K", videoUrl: "https://www.w3schools.com/html/mov_bbb.mp4" },
                { id: 3, title: "Cinematic Reel 03", category: "Color Grading • 4K", videoUrl: "https://www.w3schools.com/html/mov_bbb.mp4" },
                { id: 4, title: "Cinematic Reel 04", category: "Commercial • 4K", videoUrl: "https://www.w3schools.com/html/mov_bbb.mp4" }
              ].map((item) => (
                <motion.div key={item.id} initial={{ opacity: 0, scale: 0.95 }} whileInView={{ opacity: 1, scale: 1 }} viewport={{ once: true }} transition={{ duration: 0.5 }} className="group relative overflow-hidden rounded-[24px] aspect-[16/9] bg-white/5 border border-white/10 shadow-[0_10px_30px_rgba(0,0,0,0.3)] cursor-pointer interactive">
                  <video src={item.videoUrl} autoPlay loop muted playsInline className="absolute inset-0 w-full h-full object-cover transition-transform duration-700 group-hover:scale-105 opacity-80 group-hover:opacity-100" />
                  <div className="absolute inset-0 bg-black/60 group-hover:bg-black/20 transition-colors duration-500" />
                  <div className="absolute inset-0 p-8 flex flex-col justify-between">
                    <div className="flex justify-end"><div className="w-12 h-12 rounded-full bg-white backdrop-blur-md shadow-sm border border-white/5 flex items-center justify-center opacity-0 translate-y-4 group-hover:opacity-100 group-hover:translate-y-0 transition-all duration-300"><Play className="w-5 h-5 text-black ml-1" /></div></div>
                    <div className="translate-y-4 group-hover:translate-y-0 transition-transform duration-300"><p className="text-sm font-bold tracking-widest text-white/60 uppercase mb-2">{item.category}</p><h4 className="text-2xl font-bold text-white shadow-black drop-shadow-md">{item.title}</h4></div>
                  </div>
                </motion.div>
              ))}
            </div>
          </section>

          {/* AI Studio */}
          <section className="py-16 px-6 md:px-12 max-w-7xl mx-auto relative z-20">
            <AIConceptStudio />
          </section>

          {/* Contact Section */}
          <section id="contact" className="py-32 px-6 md:px-12 relative overflow-hidden bg-transparent">
            <div className="max-w-4xl mx-auto relative z-10 bg-white/5 border border-white/10 backdrop-blur-[20px] rounded-[3rem] p-10 md:p-20 shadow-[0_10px_50px_rgba(0,0,0,0.5)]">
              <div className="text-center mb-16">
                <h2 className="text-5xl md:text-7xl font-bold tracking-tighter mb-6 text-white">Let's Create<br/>Something Epic.</h2>
                <p className="text-xl text-white/60 font-light">Available for freelance opportunities.</p>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
                <div className="space-y-8">
                  <div>
                    <h4 className="text-sm uppercase tracking-widest text-white/50 font-semibold mb-2">Social</h4>
                    <div className="flex flex-col gap-3">
                      <a href="https://instagram.com/aura.edit_ae" className="inline-flex items-center gap-3 text-xl font-bold text-white hover:opacity-70 transition-opacity group interactive"><Instagram className="w-6 h-6" /> @aura.edit_ae</a>
                      <a href="https://github.com/vivin-m" className="inline-flex items-center gap-3 text-xl font-bold text-white hover:opacity-70 transition-opacity group interactive"><Github className="w-6 h-6" /> /vivin-m</a>
                    </div>
                  </div>
                  <div>
                    <h4 className="text-sm uppercase tracking-widest text-white/50 font-semibold mb-2">Direct</h4>
                    <a href="mailto:auraeditae@gmail.com" className="inline-flex items-center gap-3 text-xl font-bold text-white hover:opacity-70 transition-opacity group interactive"><Mail className="w-6 h-6" /> auraeditae@gmail.com</a>
                  </div>
                </div>
                <form className="space-y-6 flex flex-col" onSubmit={handleSubmit}>
                  <div className="relative group"><input type="text" name="name" required value={formState.name} onChange={handleInputChange} placeholder="Your Name" className="w-full bg-transparent border-b border-white/20 pb-4 text-lg text-white focus:outline-none focus:border-white transition-colors placeholder:text-white/40" /></div>
                  <div className="relative group"><input type="email" name="email" required value={formState.email} onChange={handleInputChange} placeholder="Your Email" className="w-full bg-transparent border-b border-white/20 pb-4 text-lg text-white focus:outline-none focus:border-white transition-colors placeholder:text-white/40" /></div>
                  <div className="relative group pt-4">
                    <div className="flex justify-between items-center mb-2"><span className="text-xs font-bold text-white/50 uppercase tracking-widest">Project Details</span><button type="button" onClick={handleDraftMessage} disabled={isDraftingMessage || !formState.message} className="text-xs font-bold text-purple-400 hover:text-purple-300 transition-colors flex items-center gap-1">{isDraftingMessage ? <Loader2 className="w-3 h-3 animate-spin" /> : <Wand2 className="w-3 h-3" />} ✨ Auto-Draft with AI</button></div>
                    <textarea placeholder="Type notes here..." name="message" required value={formState.message} onChange={handleInputChange} rows={3} className="w-full bg-transparent border-b border-white/20 pb-4 text-lg text-white focus:outline-none focus:border-white transition-colors placeholder:text-white/40 resize-none" />
                  </div>
                  <MagneticButton primary className={`py-4 mt-6 w-full sm:w-auto self-start`} disabled={isSubmitting}>{isSubmitting ? <>Sending <Loader2 className="w-4 h-4 animate-spin" /></> : isSubmitted ? <>Message Sent! <Check className="w-4 h-4 text-green-600" /></> : <>Send Message <Send className="w-4 h-4" /></>}</MagneticButton>
                </form>
              </div>
            </div>
          </section>

          <footer className="py-8 px-6 text-center border-t border-white/5 flex flex-col md:flex-row justify-between items-center max-w-7xl mx-auto text-sm text-white/40 font-medium bg-transparent">
            <p>© {new Date().getFullYear()} Aura by Vivin M.</p>
            <div className="flex items-center gap-2 mt-4 md:mt-0"><span>Crafted with</span><div className="w-2 h-2 rounded-full bg-white animate-pulse" /><span>in 4K</span></div>
          </footer>
        </motion.div>
      )}
    </>
  );
}
